SET NOCOUNT ON;
DECLARE @DependencyJson nvarchar(max),@LockScan bit=0;
-- DEPENDENCY_SCAN_HERE
DECLARE @Out nvarchar(max)=(SELECT CAST(1 AS bit) AS ok,'TEST' AS folder,@Resource AS resource,@Code AS code,
 JSON_QUERY(@DependencyJson) AS dependencies,
 (SELECT m.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT m.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.ITMMASTER m WHERE @Resource='article' AND ITMREF_0=@Code FOR JSON PATH) AS articles,
 (SELECT s.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT s.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.ITMFACILIT s WHERE @Resource='article' AND ITMREF_0=@Code FOR JSON PATH) AS sites,
 (SELECT s.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT s.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.ITMBPS s WHERE @Resource='article' AND ITMREF_0=@Code FOR JSON PATH) AS article_suppliers,
 (SELECT s.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT s.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.ITMSALES s WHERE @Resource='article' AND ITMREF_0=@Code FOR JSON PATH) AS sales,
 (SELECT a.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT a.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.ATEXTRA a WHERE @Resource='article' AND CODFIC_0='ITMMASTER' AND ZONE_0='DES1AXX' AND IDENT1_0=@Code FOR JSON PATH) AS translations,
 (SELECT p.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT p.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.BPARTNER p WHERE @Resource='supplier' AND BPRNUM_0=@Code FOR JSON PATH) AS partners,
 (SELECT s.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT s.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.BPSUPPLIER s WHERE @Resource='supplier' AND BPSNUM_0=@Code FOR JSON PATH) AS suppliers,
 (SELECT a.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT a.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.BPADDRESS a WHERE @Resource='supplier' AND BPANUM_0=@Code AND BPATYP_0=1 FOR JSON PATH) AS addresses,
 (SELECT u.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT u.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.TABUNIT u FOR JSON PATH) AS units,
 (SELECT u.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT u.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.TABCOEFF u FOR JSON PATH) AS conversions,
 (SELECT c.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT c.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.ITMCATEG c WHERE STOFCY_0='' FOR JSON PATH) AS categories,
 (SELECT u.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT u.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.TABVACITM u FOR JSON PATH) AS tax_levels,
 (SELECT t.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT t.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.TABVAT t FOR JSON PATH) AS taxes,
 (SELECT t.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT t.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.TABVAC t FOR JSON PATH) AS tax_determinations,
 (SELECT u.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT u.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.GACCCODE u WHERE TYP_0=1 FOR JSON PATH) AS accounting,
 (SELECT * FROM TEST.GACCOUNT FOR JSON PATH) AS general_accounts,
 (SELECT u.*,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT u.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)),2) AS source_hash FROM TEST.TABPAYTERM u FOR JSON PATH) AS payments,
 (SELECT z.CODFIC_0,z.CODZONE_0,l.LANNUM_0,l.LANMES_0 FROM TEST.ATABZON z JOIN TEST.APLSTD l ON l.LANCHP_0=z.NOLIB_0 AND l.LAN_0='FRA' WHERE (z.CODFIC_0='ITMMASTER' AND z.CODZONE_0 IN ('ITMSTA','NEGSTO','XFLGBPS')) OR (z.CODFIC_0='TABUNIT' AND z.CODZONE_0='UOMTYP') OR (z.CODFIC_0 IN ('BPARTNER','BPSUPPLIER') AND z.CODZONE_0='ENAFLG') FOR JSON PATH) AS menus
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);SELECT @Out;
